import{_ as e,o as a,c as i,a2 as o}from"./chunks/framework.BXzK3EA4.js";const r="/assets/ssl-2023121703.CrfSH4_d.png",n="/assets/ssl-2023121704.CqTiwb2b.png",s="/assets/ssl-2023121705.BtOKrBGY.png",l="/assets/ssl-2023121706.CzUKv_lT.png",d="/assets/ssl-2023121707.CKmPtL_U.png",c="/assets/ssl-2023121708.Dky7AxBd.png",h="/assets/336_a0a3ac99-471f-4e72-816b-1169d372d59b.C0E1GFUV.png",p="/assets/ssl-2023121710.BgE5aU5_.png",m="/assets/337_cfb09ba9-75b0-4187-8de5-5bf952ee18c2.B6De757a.png",u="/assets/338_38eecbe8-53cc-42c6-8a64-2cffe5793bca.pHzBBWPJ.png",w=JSON.parse('{"title":"SSL Certificate Validation Methods Guide","description":"","frontmatter":{"title":"SSL Certificate Validation Methods Guide"},"headers":[],"relativePath":"operations-knowledge-base/ssl/ssl-certificate-validation-methods-guide.md","filePath":"operations-knowledge-base/ssl/ssl-certificate-validation-methods-guide.md","lastUpdated":1794311093000}'),f={name:"operations-knowledge-base/ssl/ssl-certificate-validation-methods-guide.md"};function g(b,t,k,y,v,_){return a(),i("div",null,[...t[0]||(t[0]=[o('<h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>During the SSL certificate application process, <strong>Domain Control Validation (DCV)</strong> is required to verify your ownership or control of the domain. After the DCV is successfully completed, the SSL certificate is typically issued within about 30 minutes.</p><table tabindex="0"><thead><tr><th>Validation Method</th><th>Applicable Scenario</th><th>Estimated Time</th></tr></thead><tbody><tr><td>Email Validation</td><td>The domain email account can receive emails</td><td>Within minutes</td></tr><tr><td>DNS Validation</td><td>You can manage the domain DNS records</td><td>After DNS propagation takes effect</td></tr><tr><td>HTTP/HTTPS Validation</td><td>You can access the website root directory</td><td>After the file is uploaded</td></tr></tbody></table><p>⚠️ <strong>Important:</strong> For email validation, the receiving email address must be either a domain-based email address or the domain registrant email address shown in the WHOIS record. All validation steps must be completed by the customer.</p><h2 id="_2-general-input-rules" tabindex="-1">2. General Input Rules <a class="header-anchor" href="#_2-general-input-rules" aria-label="Permalink to &quot;2. General Input Rules&quot;">​</a></h2><h3 id="_2-1-domain-format-requirements" tabindex="-1">2.1 Domain Format Requirements <a class="header-anchor" href="#_2-1-domain-format-requirements" aria-label="Permalink to &quot;2.1 Domain Format Requirements&quot;">​</a></h3><p>When applying for an SSL certificate, the Domain information cannot be an IP address. It must be entered in domain format, such as <code>xxx.xxx.xxx</code>.</p><table tabindex="0"><thead><tr><th>Certificate Type</th><th>Domain Format</th><th>Example</th></tr></thead><tbody><tr><td>Single Domain Certificate</td><td>Enter the domain that needs to be bound directly</td><td><a href="http://yourdomain.com/" title="http://yourdomain.com" target="_blank" rel="noreferrer">yourdomain.com</a> / <a href="http://sub.yourdomain.com/" title="http://sub.yourdomain.com" target="_blank" rel="noreferrer">sub.yourdomain.com</a></td></tr><tr><td>Wildcard Certificate</td><td><code>*.yourdomain.com</code></td><td>*.example.com</td></tr><tr><td>Multi-Domain SAN Certificate</td><td>Enter one primary domain only. Other domains can be entered when submitting the certificate</td><td><a href="http://example.com/" target="_blank" rel="noreferrer">Example Domain</a></td></tr></tbody></table><h3 id="_2-2-common-input-errors" tabindex="-1">2.2 Common Input Errors <a class="header-anchor" href="#_2-2-common-input-errors" aria-label="Permalink to &quot;2.2 Common Input Errors&quot;">​</a></h3><p><strong>Error 1: Entering an IP address</strong><strong>Issue:</strong> An error appears when clicking <strong>“Submit”</strong> after <strong>“Save”</strong><strong>Cause:</strong> SSL certificates can only be bound to domain names, not IP addresses <strong>Solution:</strong> Change it to the correct domain format</p><p><strong>Error 2: Entering a specific domain for a wildcard certificate</strong><strong>Issue:</strong> A format error is shown during submission <strong>Cause:</strong> A wildcard certificate must use the <code>*.domain.com</code> format <strong>Solution:</strong> Change it to the wildcard format</p><h2 id="_3-email-validation" tabindex="-1">3. Email Validation <a class="header-anchor" href="#_3-email-validation" aria-label="Permalink to &quot;3. Email Validation&quot;">​</a></h2><h3 id="_3-1-steps" tabindex="-1">3.1 Steps <a class="header-anchor" href="#_3-1-steps" aria-label="Permalink to &quot;3.1 Steps&quot;">​</a></h3><p><strong>Step 1: Select the validation method</strong></p><ul><li>Enter the Domain information on the certificate application page</li><li>Select the <strong>“DCV method”</strong> as the email validation address</li><li>Click <strong>“Save”</strong></li><li>Click <strong>“Submit”</strong></li></ul><p><img src="'+r+'" alt=""></p><p><strong>Step 2: Confirm submission</strong></p><p>After the submission is successful, the page will jump to the confirmation page.</p><p><img src="'+n+'" alt=""></p><p><strong>Step 3: Check the email and complete validation</strong></p><ul><li>Log in to your mailbox and check the validation email sent by the certificate authority</li><li>The email will contain a verification code and a verification link</li><li>Click the <strong>“here”</strong> link in the email to open the verification page</li><li>Enter the verification code from the email on the verification page</li><li>Click <strong>“Next”</strong> to complete the validation</li></ul><p><img src="'+s+'" alt=""></p><p><img src="'+l+'" alt=""></p><p><img src="'+d+'" alt=""></p><h3 id="_3-2-validation-completed" tabindex="-1">3.2 Validation Completed <a class="header-anchor" href="#_3-2-validation-completed" aria-label="Permalink to &quot;3.2 Validation Completed&quot;">​</a></h3><ul><li>The page will display that the validation was successful</li><li>The certificate status will be updated to validated</li></ul><hr><h2 id="_4-dns-validation" tabindex="-1">4. DNS Validation <a class="header-anchor" href="#_4-dns-validation" aria-label="Permalink to &quot;4. DNS Validation&quot;">​</a></h2><h3 id="_4-1-steps" tabindex="-1">4.1 Steps <a class="header-anchor" href="#_4-1-steps" aria-label="Permalink to &quot;4.1 Steps&quot;">​</a></h3><p><strong>Step 1: Select the validation method</strong></p><ul><li>Enter the Domain information</li><li>Select the <strong>“DCV method”</strong> as <strong>“DNS validation”</strong></li><li>Click <strong>“Save”</strong></li><li>Click <strong>“Submit”</strong></li></ul><p><img src="'+c+'" alt=""></p><p><strong>Step 2: Obtain the validation information</strong> After submission, the system will generate a DNS validation record, including:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td>Host</td><td>Host record</td><td><code>_dnsauth.yourdomain.com</code></td></tr><tr><td>Type</td><td>Record type</td><td><code>CNAME</code></td></tr><tr><td>Value</td><td>Record value</td><td><code>_dnsauth.yourdomain.com.xxx.xxx.com</code></td></tr></tbody></table><p><strong>Step 3: Add the record in DNS management</strong></p><ul><li>Log in to your domain DNS management panel</li><li>Find the domain that needs to be validated, and enter the validation value in the subdomain record section</li><li>Fill in the record according to the information provided by the system</li></ul><p><img src="'+h+'" alt=""></p><p><strong>Step 3.1: Verify that the DNS record has taken effect</strong></p><p>After adding the DNS record, you can use a DNS lookup tool to check whether the record has taken effect.</p><p>Visit <a href="https://www.racent.com/dns-check" target="_blank" rel="noreferrer">DNS Lookup / DNS Record Query</a> , enter your domain and host record, and check the resolution status. If it shows that the record has taken effect, the system will automatically complete the certificate validation.</p><hr><h2 id="_5-http-https-validation" tabindex="-1">5. HTTP/HTTPS Validation <a class="header-anchor" href="#_5-http-https-validation" aria-label="Permalink to &quot;5. HTTP/HTTPS Validation&quot;">​</a></h2><h3 id="_5-1-steps" tabindex="-1">5.1 Steps <a class="header-anchor" href="#_5-1-steps" aria-label="Permalink to &quot;5.1 Steps&quot;">​</a></h3><p><strong>Step 1: Select the validation method</strong></p><ul><li>Enter the Domain information</li><li>Select the <strong>“DCV method”</strong> as <strong>“HTTP validation”</strong></li><li>Click <strong>“Save”</strong></li><li>Click <strong>“Submit”</strong></li></ul><p><img src="'+p+'" alt=""></p><p><strong>Step 2: Obtain the validation file information</strong></p><p>The system will generate a validation file that needs to be created in the website root directory:</p><table tabindex="0"><thead><tr><th>Item</th><th>Example</th></tr></thead><tbody><tr><td>File Path</td><td><code>/.well-known/pki-validation/filename.txt</code></td></tr><tr><td>File Content</td><td>verification code + CA domain</td></tr><tr><td>Validation URL</td><td><code>http://yourdomain.com/.well-known/pki-validation/filename.txt</code></td></tr></tbody></table><p><strong>Step 3: Create the validation file in the website root directory</strong></p><p><strong>Example for Linux / Apache / Nginx environments:</strong></p><h2 id="enter-the-website-root-directory-adjust-the-path-according-to-your-actual-environment" tabindex="-1">Enter the website root directory (adjust the path according to your actual environment) <a class="header-anchor" href="#enter-the-website-root-directory-adjust-the-path-according-to-your-actual-environment" aria-label="Permalink to &quot;Enter the website root directory (adjust the path according to your actual environment)&quot;">​</a></h2><p>“cd /var/www/html”</p><h2 id="create-the-required-directory" tabindex="-1">Create the required directory <a class="header-anchor" href="#create-the-required-directory" aria-label="Permalink to &quot;Create the required directory&quot;">​</a></h2><p>“mkdir -p .well-known/pki-validation”</p><h2 id="enter-the-directory" tabindex="-1">Enter the directory <a class="header-anchor" href="#enter-the-directory" aria-label="Permalink to &quot;Enter the directory&quot;">​</a></h2><p>“cd .well-known/pki-validation”</p><h2 id="create-the-validation-file-and-write-the-content-echo-205acf83f2718baa25ead1cd95bb2891b8e2c4818586a5bea3046f16b37b080f-comodoca-com-007bddfac9157321d1071420be72fea8-txt" tabindex="-1">Create the validation file and write the content echo &quot;205acf83f2718baa25ead1cd95bb2891b8e2c4818586a5bea3046f16b37b080f comodoca.com&quot; &gt; 007BDDFAC9157321D1071420BE72FEA8.txt <a class="header-anchor" href="#create-the-validation-file-and-write-the-content-echo-205acf83f2718baa25ead1cd95bb2891b8e2c4818586a5bea3046f16b37b080f-comodoca-com-007bddfac9157321d1071420be72fea8-txt" aria-label="Permalink to &quot;Create the validation file and write the content echo &quot;205acf83f2718baa25ead1cd95bb2891b8e2c4818586a5bea3046f16b37b080f comodoca.com&quot; &gt; 007BDDFAC9157321D1071420BE72FEA8.txt&quot;">​</a></h2><h2 id="set-file-permissions-make-sure-it-is-accessible" tabindex="-1">Set file permissions (make sure it is accessible) <a class="header-anchor" href="#set-file-permissions-make-sure-it-is-accessible" aria-label="Permalink to &quot;Set file permissions (make sure it is accessible)&quot;">​</a></h2><p>“chmod 644 007BDDFAC9157321D1071420BE72FEA8.txt”</p><h2 id="restart-the-web-service-optional-to-make-the-configuration-take-effect" tabindex="-1">Restart the web service (optional, to make the configuration take effect) <a class="header-anchor" href="#restart-the-web-service-optional-to-make-the-configuration-take-effect" aria-label="Permalink to &quot;Restart the web service (optional, to make the configuration take effect)&quot;">​</a></h2><p>&quot; /etc/init.d/apache2 restart”</p><h2 id="or-systemctl-restart-nginx" tabindex="-1">Or “systemctl restart nginx” <a class="header-anchor" href="#or-systemctl-restart-nginx" aria-label="Permalink to &quot;Or  “systemctl restart nginx”&quot;">​</a></h2><p><strong>Windows / IIS environment:</strong></p><ul><li>Create a folder named <code>.well-known</code> in the website root directory</li><li>Create a folder named <code>pki-validation</code> inside <code>.well-known</code></li><li>Create a text file in the <code>pki-validation</code> folder, for example: <code>007BDDFAC9157321D1071420BE72FEA8.txt</code></li><li>Open the file with Notepad and paste the content provided by the system</li><li>Save the file</li></ul><p><strong>Step 4: Test whether the file can be accessed</strong></p><p>Open the validation URL in a browser:</p><ul><li>✅ Normal: the browser displays the file content</li><li>❌ Abnormal: <code>404 Not Found</code> or the file cannot be accessed</li></ul><h3 id="_5-2-validation-completed" tabindex="-1">5.2 Validation Completed <a class="header-anchor" href="#_5-2-validation-completed" aria-label="Permalink to &quot;5.2 Validation Completed&quot;">​</a></h3><p>After the file becomes accessible, the system will automatically detect it and complete the validation.</p><p><strong>Certificate issuance time:</strong> After any of the above validation methods is completed, the SSL certificate is usually issued within about 30 minutes.</p><h2 id="_6-frequently-asked-questions" tabindex="-1">6. Frequently Asked Questions <a class="header-anchor" href="#_6-frequently-asked-questions" aria-label="Permalink to &quot;6. Frequently Asked Questions&quot;">​</a></h2><h3 id="_6-1-what-should-i-do-if-the-certificate-is-still-not-issued-after-application" tabindex="-1">6.1 What should I do if the certificate is still not issued after application? <a class="header-anchor" href="#_6-1-what-should-i-do-if-the-certificate-is-still-not-issued-after-application" aria-label="Permalink to &quot;6.1 What should I do if the certificate is still not issued after application?&quot;">​</a></h3><p>If the certificate remains in <strong>“Pending”</strong> status for a long time, you can try the following:</p><ul><li>Visit the certificate status check tool: <strong>Sectigo Order Status Checker</strong></li><li>Select the purchased certificate order</li><li>On the DCV validation information page, locate the two validation configuration options</li><li>First change it to another option, then click <strong>“Save your changes”</strong></li><li>Then change it back to the original option and click <strong>“Save your changes”</strong> again</li><li>If the configuration is correct, it will usually take effect immediately</li></ul><p><img src="'+m+'" alt=""></p><h3 id="_6-2-what-should-i-do-if-i-entered-incorrect-information-during-the-certificate-application-process" tabindex="-1">6.2 What should I do if I entered incorrect information during the certificate application process? <a class="header-anchor" href="#_6-2-what-should-i-do-if-i-entered-incorrect-information-during-the-certificate-application-process" aria-label="Permalink to &quot;6.2 What should I do if I entered incorrect information during the certificate application process?&quot;">​</a></h3><p><strong>Pending status:</strong> The domain cannot be changed. You must wait until the certificate is issued, or cancel it and apply again.</p><p><strong>Issued status:</strong> You can click <strong>“Replace”</strong> in the backend to change the domain.</p><p><img src="'+u+'" alt=""></p><h3 id="_6-3-what-should-i-do-if-i-accidentally-clicked-the-cancel-button" tabindex="-1">6.3 What should I do if I accidentally clicked the Cancel button? <a class="header-anchor" href="#_6-3-what-should-i-do-if-i-accidentally-clicked-the-cancel-button" aria-label="Permalink to &quot;6.3 What should I do if I accidentally clicked the Cancel button?&quot;">​</a></h3><p><strong>Cancelled status explanation:</strong></p><ul><li>A cancelled status cannot be restored</li><li>No further operations can be performed</li><li>You need to purchase the certificate again</li></ul><hr><h2 id="_7-technical-support" tabindex="-1">7. Technical Support <a class="header-anchor" href="#_7-technical-support" aria-label="Permalink to &quot;7. Technical Support&quot;">​</a></h2><p>If you encounter any validation issues, you can contact us in the following way:</p><p>Submit a ticket: Click <strong>“Submit Ticket”</strong> in the upper-right corner of the backend.</p>',87)])])}const x=e(f,[["render",g]]);export{w as __pageData,x as default};
